/// HTTPS that trusts the Mozilla root certificates compiled in: the same on every machine.
fn tls() -> rustls::ClientConfig {
    let roots = rustls::RootCertStore::from_iter(webpki_roots::TLS_SERVER_ROOTS.iter().cloned());
    // The provider is named. Left to rustls, it is the process's default one, and a build where
    // another crate turns on a second provider has none: making a client would panic.
    let provider = Arc::new(rustls::crypto::aws_lc_rs::default_provider());

    rustls::ClientConfig::builder_with_provider(provider)
        .with_safe_default_protocol_versions()
        .expect("aws-lc-rs has cipher suites for rustls's default TLS versions")
        .with_root_certificates(roots)
        .with_no_client_auth()
}
